import { describe, expect, it } from "vitest";

import { resolveClassInvitationStatus } from "./class-invitation-status";

const validToken = "a".repeat(64);
const now = () => new Date("2026-10-02T12:00:00.000Z");

describe("resolveClassInvitationStatus", () => {
  it.each([
    [null, "missing"],
    ["not-a-token", "invalid"],
  ] as const)("returns %s for a %s token", async (token, expected) => {
    await expect(resolveClassInvitationStatus(token, null)).resolves.toBe(expected);
  });

  it("treats unknown and rotated prior token digests as the same invalid state", async () => {
    const dependencies = {
      digestToken: () => Promise.resolve("digest"),
      findInvitation: () => Promise.resolve(null),
    };
    await expect(resolveClassInvitationStatus(validToken, null, dependencies)).resolves.toBe("invalid");
  });

  it("classifies expired and failed deliveries without exposing recipient data", async () => {
    await expect(
      resolveClassInvitationStatus(validToken, null, {
        digestToken: () => Promise.resolve("digest"),
        findInvitation: () =>
          Promise.resolve({
            normalizedEmail: "student@example.test",
            expiresAt: "2026-10-01T12:00:00.000Z",
            deliveryState: "sent" as const,
          }),
        now,
      }),
    ).resolves.toBe("expired");
    await expect(
      resolveClassInvitationStatus(validToken, null, {
        digestToken: () => Promise.resolve("digest"),
        findInvitation: () =>
          Promise.resolve({
            normalizedEmail: "student@example.test",
            expiresAt: "2026-10-03T12:00:00.000Z",
            deliveryState: "failed" as const,
          }),
        now,
      }),
    ).resolves.toBe("delivery-failed");
    await expect(
      resolveClassInvitationStatus(validToken, null, {
        digestToken: () => Promise.resolve("digest"),
        findInvitation: () =>
          Promise.resolve({
            normalizedEmail: "student@example.test",
            expiresAt: "2026-10-03T12:00:00.000Z",
            deliveryState: "pending" as const,
          }),
        now,
      }),
    ).resolves.toBe("delivery-failed");
  });

  it("distinguishes unauthenticated, matching, and mismatched accounts without returning an email", async () => {
    const dependencies = {
      digestToken: () => Promise.resolve("digest"),
      findInvitation: () =>
        Promise.resolve({
          normalizedEmail: "student@example.test",
          expiresAt: "2026-10-03T12:00:00.000Z",
          deliveryState: "sent" as const,
        }),
      now,
    };
    await expect(resolveClassInvitationStatus(validToken, null, dependencies)).resolves.toBe("valid");
    await expect(resolveClassInvitationStatus(validToken, "other@example.test", dependencies)).resolves.toBe(
      "email-mismatch",
    );
    await expect(resolveClassInvitationStatus(validToken, " STUDENT@example.test ", dependencies)).resolves.toBe(
      "ready",
    );
  });
});

src/lib/services/resend-class-invitation.source:
import { describe, expect, it, vi } from "vitest";

import {
  ResendClassInvitationError,
  type ResendEmailClient,
  sendResendClassInvitation,
} from "./resend-class-invitation";

const config = {
  apiKey: "test-key",
  fromEmail: "Klasy <classes@example.test>",
  appOrigin: "https://app.example.test/",
};

describe("sendResendClassInvitation", () => {
  it("sends a Polish escaped email with a stable invitation URL", async () => {
    const send = vi
      .fn<ResendEmailClient["emails"]["send"]>()
      .mockResolvedValue({ data: { id: "provider-message-id" }, error: null });

    await expect(
      sendResendClassInvitation(
        { className: "4A <math>", recipientEmail: "student@example.test", token: "raw-token" },
        config,
        { client: { emails: { send } }, clock: () => new Date("2026-10-02T12:00:00.000Z") },
      ),
    ).resolves.toEqual({ providerMessageId: "provider-message-id" });

    const sentMessage = send.mock.calls[0]?.[0];
    expect(sentMessage.to).toEqual(["student@example.test"]);
    expect(sentMessage.html).toContain("4A &lt;math&gt;");
    expect(sentMessage.text).toContain("https://app.example.test/classes/join?token=raw-token");
  });

  it("removes line breaks from the email subject", async () => {
    const send = vi
      .fn<ResendEmailClient["emails"]["send"]>()
      .mockResolvedValue({ data: { id: "provider-message-id" }, error: null });

    await sendResendClassInvitation(
      { className: "4A\r\nBcc: injected@example.test", recipientEmail: "student@example.test", token: "raw-token" },
      config,
      { client: { emails: { send } } },
    );

    expect(send.mock.calls[0]?.[0].subject).toBe("Zaproszenie do klasy 4A Bcc: injected@example.test");
  });

  it("classifies provider failures without exposing their details", async () => {
    const send = vi
      .fn<ResendEmailClient["emails"]["send"]>()
      .mockRejectedValue(new Error("recipient-specific provider diagnostic"));

    await expect(
      sendResendClassInvitation(
        { className: "4A", recipientEmail: "student@example.test", token: "raw-token" },
        config,
        { client: { emails: { send } } },
      ),
    ).rejects.toEqual(new ResendClassInvitationError("PROVIDER_FAILURE"));
  });
});

