  });

  it("exposes Polish labels for every difficulty", () => {
    expect(Object.keys(DIFFICULTY_LABELS)).toEqual(EXERCISE_DIFFICULTIES);
    expect(Object.values(DIFFICULTY_LABELS)).toEqual(["Łatwy", "Średni", "Trudny"]);
  });
});

